{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Rufinamide, a carboxamide-containing small molecule, has 85% oral bioavailability in patients, supporting that the query's carboxamide motif is compatible with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Zalcitabine, a polar nucleoside analog, has absolute oral bioavailability of 88% in patients, directly supporting high F for a nucleoside scaffold like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Lamivudine, another nucleoside analog, shows 87% absolute oral bioavailability in patients, reinforcing high absorption for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C82"],
      "claim": "Dapagliflozin, a glycoside, has 78% absolute oral bioavailability in healthy subjects, supporting that sugar-containing molecules can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C76"],
      "claim": "Didanosine, a dideoxypurine nucleoside, has low oral bioavailability (~22% fasting), but this is attributed to acid lability and first-pass degradation, which are not expected for the stable ribosyl imidazole query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence, especially from nucleoside and glycoside analogs, shows oral bioavailability well above 20%; the only low-F analog (didanosine) owes its poor F to acid lability not shared by the query. Therefore high F is better supported.",
  "evidence_gaps": [
    "No direct acadesine oral bioavailability record is present; prediction relies on analogical evidence.",
    "Uncertainty remains about first-pass phosphorylation/metabolism of the ribosyl imidazole nucleoside in humans."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

